/**
 * FoodShareAI - Demand Forecast Model
 * Stores time-series predictions generated by our PyTorch LSTM demand model.
 * Enables operational intelligence, supply-demand gap analysis, and smart matching hints.
 */
const mongoose = require('mongoose');
const { FOOD_CATEGORIES } = require('../utils/constants');

const categoryBreakdownItemSchema = new mongoose.Schema(
  {
    category: {
      type: String,
      required: true,
      trim: true,
    },
    supply: {
      type: Number,
      default: 0,
    },
    demand: {
      type: Number,
      default: 0,
    },
    gap: {
      type: Number,
      default: 0, // supply - demand
    },
    status: {
      type: String,
      enum: ['Deficit', 'Surplus', 'Balanced'],
      default: 'Balanced',
    },
  },
  { _id: false }
);

const pointSchema = new mongoose.Schema(
  {
    type: {
      type: String,
      enum: ['Point'],
      default: 'Point',
    },
    coordinates: {
      type: [Number],
      default: [78.4867, 17.385], // Default Hyderabad metro center
    },
  },
  { _id: false }
);

const demandForecastSchema = new mongoose.Schema(
  {
    foodCategory: {
      type: String,
      required: true,
      enum: [...FOOD_CATEGORIES, 'ALL'],
      default: 'ALL',
      index: true,
    },
    location: {
      type: pointSchema,
      default: () => ({ type: 'Point', coordinates: [78.4867, 17.385] }),
    },
    forecastPeriod: {
      type: String,
      enum: ['24_HOURS', '7_DAYS', '30_DAYS', 'ALL'],
      default: '24_HOURS',
      index: true,
    },
    todaySupply: {
      type: Number,
      default: 0,
    },
    todayDemand: {
      type: Number,
      default: 0,
    },
    gapMeals: {
      type: Number,
      default: 0,
    },
    forecast24h: {
      type: Number,
      default: 0,
    },
    forecast7d: {
      type: Number,
      default: 0,
    },
    forecast30d: {
      type: Number,
      default: 0,
    },
    confidence: {
      type: Number,
      min: 0,
      max: 1,
      default: 0,
    },
    modelVersion: {
      type: String,
      default: 'demand_lstm_v1',
      trim: true,
    },
    status: {
      type: String,
      enum: ['PENDING', 'PROCESSING', 'COMPLETED', 'FAILED', 'MODEL_NOT_LOADED', 'INSUFFICIENT_DATA'],
      default: 'COMPLETED',
      index: true,
    },
    categoryBreakdown: [categoryBreakdownItemSchema],
    inputDataRange: {
      startDate: { type: Date, default: null },
      endDate: { type: Date, default: null },
      dataPointsCount: { type: Number, default: 0 },
    },
    evaluationMetrics: {
      mae: { type: Number, default: null },
      mse: { type: Number, default: null },
      sequenceLength: { type: Number, default: 7 },
    },
    generatedAt: {
      type: Date,
      default: Date.now,
      index: true,
    },
  },
  {
    timestamps: true,
  }
);

demandForecastSchema.index({ foodCategory: 1, forecastPeriod: 1, createdAt: -1 });
demandForecastSchema.index({ location: '2dsphere' });

const DemandForecast = mongoose.model('DemandForecast', demandForecastSchema);

module.exports = DemandForecast;
